# Hand-written explanations of the external provider fields. Keys: "Common.X" (every kind), "Oidc.X", "Saml.X", "Ldap.X". Examples are the field inside a provider JSON.
N = {}
def n(key, what, when, why, ex=None): N[key] = dict(what=what, when=when, why=why, ex=ex)

n('Common.Name', 'The provider\'s name inside the project: lowercase letters, digits and `-`, 1 to 40 characters, unique in the project. It is used in the callback and SAML URLs, as the login provider name in `user_logins`, and in the `idp` claim.', 'When you create the provider. **It cannot change later.**', 'Links and URLs depend on it; changing it would orphan the users\' links.', 'google')
n('Common.Type', 'The kind of provider (`ExternalProviderType`). It selects the engine and the extra fields. **It cannot change later.** See [enums-reference.md](enums-reference.md#externalprovidertype).', 'When you create the provider.', 'Each kind has different protocol rules.', 'Google')
n('Common.DisplayName', 'The text of the sign-in button.', 'To show something friendlier than the name.', 'People recognise "Sign in with Google" better than `google`.', 'Sign in with Google')
n('Common.Enabled', 'Switches the provider on. A disabled provider is not offered and its URLs answer with an error. An enabled provider must have its client id and secret (or trust material, or a bind account).', 'After the settings are complete and the test route says `ok`.', 'You can prepare a provider without exposing it.', True)
n('Common.AllowRegister', 'A **new** person may be created from this provider\'s sign-in.', 'Turn off when only existing users may sign in with it (an invite-only project).', 'Otherwise anyone with a Google account could create an account.', False)
n('Common.AllowLink', 'A sign-in may join an **existing** person with the same **verified** email.', 'Turn off if provider accounts must never attach to existing local accounts.', 'Linking by email is convenient but only safe when the email is proven (see `TrustProviderEmailVerification`).', True)
n('Common.TrustProviderEmailVerification', 'Whether the provider\'s "email is verified" counts as proof of ownership. `null` uses the default of the type: **yes** for Google, Microsoft and Apple, **no** for the others. Only a global admin may turn it on.', 'On for a provider you control (your own Keycloak, your SAML identity provider).', 'An unproven email must never log someone into an existing account (account takeover).', True)
n('Common.TrustProviderMfa', 'The provider\'s own multi-factor sign-in replaces the local authenticator step. Only a global admin may turn it on. See [two-factor.md](two-factor.md#other-ways-to-sign-in).', 'When the provider enforces MFA itself (Entra ID conditional access).', 'Without it people would be asked twice.', True)
n('Common.ClaimMappings', 'Maps the provider\'s claim or attribute names to local fields (`email`, `given_name`, `family_name`, `name`, `phone_number`, `picture`).', 'When the provider uses other names (`mail`, `surname`).', 'Providers disagree on claim names.', {'mail': 'email', 'surname': 'family_name'})
n('Common.GroupMappingMode', '`None` ignores groups; `Sync` applies the group mappings at every sign-in. See [enums-reference.md](enums-reference.md#groupmappingmode) and [group-mapping.md](external-identity/group-mapping.md).', 'When provider groups should give local roles.', 'Roles in one place (the directory) instead of two.', 'Sync')
n('Common.ProfileSyncMode', '`ImportOnce` copies names and phone when the user is created; `UpdateOnLogin` refreshes them at each sign-in. See [enums-reference.md](enums-reference.md#profilesyncmode).', '`UpdateOnLogin` for a company directory.', 'Decides who owns the profile data.', 'UpdateOnLogin')
n('Common.AutoRedirect', 'Go straight to this provider when it is the only way to sign in.', 'A project that uses only the company single sign-on.', 'One click fewer.', True)
n('Common.EmailDomains', 'Email domains that are sent to this provider (home-realm discovery): a person who types `sara@corp.com` is suggested this provider. A domain belongs to one provider per project.', 'One provider per customer company.', 'Skips the "which provider?" question.', ['corp.com'])

# OIDC
n('Oidc.ClientId', 'The client id from the provider\'s console. **Required** for an enabled provider.', 'When you register the Server at the provider.', 'It identifies your Server to the provider.', '1234-abc.apps.googleusercontent.com')
n('Oidc.ClientSecretProtected', 'The client secret, **encrypted**. Sent as `clientSecret` in plain once; never returned (the list shows `secretIsSet`). Rotate with `POST .../rotate-secret`.', 'When the provider rotates the secret.', 'A secret must not be readable from the database or an answer.', None)
n('Oidc.Scopes', 'Extra scopes to ask the provider for (the type adds its own defaults).', 'When you need claims beyond the defaults.', 'Ask for as little as you need.', ['openid', 'email', 'profile'])
n('Oidc.StoreProviderTokens', 'Keep the provider\'s access and refresh tokens. Off by default: upstream tokens are never stored in the Server\'s token table.', 'Only if your code later calls the provider as the person.', 'Stored tokens are a target; keep none you do not use.', False)
n('Oidc.HostedDomain', '**Google**: only accounts of this Google Workspace domain may sign in (the `hd` claim is checked too).', 'A company product on Google Workspace.', 'Personal Gmail accounts are refused.', 'corp.com')
n('Oidc.TenantId', '**Microsoft**: `common`, `organizations`, `consumers` or a tenant GUID. Default `common`.', 'A specific tenant for a company product.', 'Limits who may sign in; a wrong tenant fails at the issuer check.', 'common')
n('Oidc.AllowedTenants', '**Microsoft**: the tenant ids allowed when `TenantId` is `common` or `organizations`.', 'A partner program with a few tenants.', 'An allow-list instead of "any work account".', ['11111111-2222-3333-4444-555555555555'])
n('Oidc.RequireVerifiedPrimaryEmail', '**GitHub**: use only the primary email and only when GitHub says it is verified (default `true`).', 'Leave on.', 'Otherwise a person could present an email they do not own.', True)
n('Oidc.AllowedOrganizations', '**GitHub**: the person must belong to one of these organizations.', 'A tool for one GitHub organization.', 'Restricts sign-in to your team.', ['my-org'])
n('Oidc.TeamId', '**Apple**: the Apple developer team id.', 'With Sign in with Apple.', 'Part of the signed client assertion Apple needs.', 'ABCDE12345')
n('Oidc.KeyId', '**Apple**: the id of the private key you made.', 'With Sign in with Apple.', 'Apple needs it to verify the assertion.', 'ABC123DEFG')
n('Oidc.PrivateKeyProtected', '**Apple**: the private key (`.p8`), encrypted. Apple has no client secret: a short-lived signed token is made from this key.', 'With Sign in with Apple.', 'Same secrecy rules as a client secret.', None)
n('Oidc.ApiVersion', '**Facebook**: the Graph API version, for example `v19.0`; applied to the library\'s endpoints.', 'When Facebook retires a version.', 'Pins the behaviour you tested.', 'v19.0')
n('Oidc.Authority', '**GenericOidc**: the issuer address (https) from which `/.well-known/openid-configuration` is read.', 'Keycloak, Okta, Auth0 and others.', 'Everything else is discovered from it.', 'https://sso.example.com/realms/corp')
n('Oidc.NameClaim', '**GenericOidc**: the claim with the person\'s name.', 'When it is not `name`.', 'Providers differ.', 'preferred_username')
n('Oidc.EmailClaim', '**GenericOidc**: the claim with the email.', 'When it is not `email`.', 'Providers differ.', 'mail')
n('Oidc.GroupsClaim', '**GenericOidc**: the claim with the groups, for group mapping.', 'With `GroupMappingMode = Sync`.', 'Needs the provider to send groups.', 'groups')
n('Oidc.AllowedIssuers', '**GenericOidc**: extra issuers accepted in tokens (for providers whose tokens carry a different issuer than the discovery address).', 'Multi-tenant providers.', 'The issuer is checked strictly otherwise.', ['https://sso.example.com'])

# SAML
n('Saml.IdpMetadataUrl', 'An https address of the identity provider\'s metadata. The Server reads it and keeps itself up to date (certificate changes).', 'The best way to configure SAML.', 'Updates itself; no copy-paste.', 'https://idp.corp.com/metadata')
n('Saml.IdpMetadataXml', 'The metadata as text, when the identity provider has no public address.', 'A closed identity provider.', 'Does not update itself.', '<EntityDescriptor ...>')
n('Saml.IdpEntityId', 'The identity provider\'s entity id (manual setup only).', 'Without metadata.', 'Identifies the issuer of assertions.', 'https://idp.corp.com')
n('Saml.IdpSsoUrl', 'The identity provider\'s single sign-on address (manual setup only).', 'Without metadata.', 'Where the request is sent.', 'https://idp.corp.com/sso')
n('Saml.IdpSloUrl', 'The identity provider\'s single logout address.', 'With `AllowSingleLogout`.', 'Where logout messages go.', 'https://idp.corp.com/slo')
n('Saml.IdpSigningCertificates', 'The certificates the identity provider signs with (at most two, for a rotation). **Pinned**: an assertion signed by another key is refused.', 'Manual setup, or to pin explicitly.', 'The trust anchor of the whole flow.', ['-----BEGIN CERTIFICATE-----...'])
n('Saml.SpEntityId', 'The Server\'s own entity id for this provider. Default: `https://{issuer}/saml/{slug}/{name}`.', 'When the identity provider already has a fixed one.', 'The audience of the assertion.', 'https://auth.example.com/saml/papertrade/corp-saml')
n('Saml.NameIdFormat', '`Persistent` by default. See [enums-reference.md](enums-reference.md#samlnameidformat).', 'Rarely.', 'A stable NameID is how a person stays the same person.', 'Persistent')
n('Saml.AuthnRequestBinding', '`Redirect` by default or `Post`. See [enums-reference.md](enums-reference.md#samlbinding).', 'When the identity provider only takes a form post.', 'Some providers refuse the redirect binding.', 'Post')
n('Saml.SignAuthnRequests', 'Sign the request the Server sends (needs the service-provider certificate: `POST .../saml/generate-sp-certificate`).', 'When the identity provider demands signed requests.', 'Proves the request comes from your Server.', True)
n('Saml.WantAssertionsSigned', 'Require the assertion to be signed (default `true`). Either the assertion or the response must be signed; a provider with neither is refused.', 'Leave on.', 'An unsigned assertion could be forged.', True)
n('Saml.WantResponseSigned', 'Require the whole response to be signed too.', 'When the identity provider signs responses.', 'Defence in depth; required for IdP-initiated sign-in.', True)
n('Saml.WantAssertionsEncrypted', 'Require encrypted assertions (uses the service-provider certificate).', 'When the identity provider can encrypt.', 'Keeps attributes private on the browser path.', True)
n('Saml.SpSigningCertificateProtected', 'The Server\'s own certificate and private key for this provider, **encrypted**. Made by `POST .../saml/generate-sp-certificate`; only the public part is returned.', 'To sign requests or decrypt assertions.', 'Rotation steps: [saml-certificate-rotation.md](external-identity/saml-certificate-rotation.md).', None)
n('Saml.ForceAuthn', 'Ask the identity provider to sign the person in again even if they have a session.', 'Sensitive applications.', 'Stops a stale single-sign-on session from being reused.', True)
n('Saml.AllowIdpInitiated', 'Accept a sign-in that starts at the identity provider (no request from the Server). Off by default; only a global admin may turn it on; the response must then be signed as a whole.', 'When the company portal links straight into your app.', 'IdP-initiated sign-in cannot be bound to a request, so it is a bigger risk.', True)
n('Saml.ClockSkewSeconds', 'Time difference allowed when checking the assertion\'s validity window (default 60, at most 300).', 'Identity provider clocks that drift.', 'Fix the clock rather than raising this.', 120)
n('Saml.AttributeMappings', 'Maps attribute names of the assertion to local fields.', 'When the attribute names are not the standard ones.', 'Identity providers name attributes freely.', {'mailaddress': 'email'})
n('Saml.GroupsAttribute', 'The attribute that carries the groups, for group mapping.', 'With `GroupMappingMode = Sync`.', 'Tells the Server where the groups are.', 'groups')
n('Saml.EmailAttribute', 'The attribute that carries the email.', 'When it is not mapped by `AttributeMappings`.', 'The email links and identifies the person.', 'mail')
n('Saml.SubjectAttribute', 'Use this attribute as the stable id of the person instead of the NameID.', 'When the NameID is transient or an email that changes.', 'A stable id such as an employee number avoids duplicate accounts.', 'employeeNumber')
n('Saml.RequiredAuthnContext', 'The authentication context the identity provider must use (for example a multi-factor class).', 'To demand a stronger sign-in at the identity provider.', 'The Server then refuses weaker answers.', 'urn:oasis:names:tc:SAML:2.0:ac:classes:MobileTwoFactorContract')
n('Saml.AllowSingleLogout', 'Accept a signed logout request from the identity provider at `/saml/{slug}/{name}/slo`. Off by default. Logout started in the Server stays local.', 'When the identity provider should sign people out of your app.', 'One logout everywhere.', True)

# LDAP
n('Ldap.Host', 'The directory server name. **Required.**', 'Always.', 'Where to connect.', 'dc.corp.com')
n('Ldap.Port', 'The port: 636 (LDAPS, default) or 389 (StartTLS).', 'Match `Security`.', 'A mismatch is the usual connect error.', 636)
n('Ldap.Security', '`Ldaps` or `StartTls`. Plain LDAP is not offered. See [enums-reference.md](enums-reference.md#ldapsecurity).', 'Match your directory.', 'The password must not cross the network in clear text.', 'Ldaps')
n('Ldap.ValidateServerCertificate', 'Check the directory\'s certificate chain and name (default `true`). Only a global admin may turn it off.', 'Never in production.', 'Without it a man in the middle can read the service account password and every sign-in.', True)
n('Ldap.CustomCaCertificate', 'A PEM certificate of your company CA, to trust a private certificate authority.', 'A directory with a private CA.', 'The operating system store does not know your CA.', '-----BEGIN CERTIFICATE-----...')
n('Ldap.TlsServerName', 'The name that must be in the directory certificate (use a host name, not an IP address).', 'When you connect by another name than the certificate has.', 'Name checking needs a name.', 'dc.corp.com')
n('Ldap.BindDn', 'The service account that searches users. **Required.** No anonymous bind, no empty password.', 'Always.', 'The Server must find the person before it can check the password.', 'CN=svc-auth2,OU=Service Accounts,DC=corp,DC=com')
n('Ldap.BindPasswordProtected', 'The service account password, **encrypted**. Sent as `bindPassword` once; never returned.', 'When it changes (`rotate-secret`).', 'A directory secret must not be readable.', None)
n('Ldap.UserSearchBase', 'Where in the directory tree to search for users. **Required.**', 'Always.', 'Narrow it to speed up and to limit who can sign in.', 'DC=corp,DC=com')
n('Ldap.UserSearchFilter', 'The LDAP filter that finds one user; `{0}` must appear exactly once and is replaced by the (escaped) user name. **Required.**', 'Pick the filter for what people type (account name or email).', 'Escaping `{0}` stops filter injection.', '(&(objectClass=user)(objectCategory=person)(sAMAccountName={0}))')
n('Ldap.UserNameAttribute', 'The attribute with the user name (`uid` for OpenLDAP, `sAMAccountName` for Active Directory).', 'Active Directory.', 'Becomes the local user name.', 'sAMAccountName')
n('Ldap.UniqueIdAttribute', 'The stable id of the entry (`entryUUID`, or `objectGUID` for Active Directory). It is the **link key** (never the DN).', 'Active Directory.', 'A DN changes when someone is moved; a unique id does not.', 'objectGUID')
n('Ldap.EmailAttribute', 'The attribute with the email (default `mail`).', 'Rarely.', 'The email is how the person is matched and contacted.', 'mail')
n('Ldap.FirstNameAttribute', 'The attribute with the first name (default `givenName`).', 'Rarely.', 'Fills the profile.', 'givenName')
n('Ldap.LastNameAttribute', 'The attribute with the last name (default `sn`).', 'Rarely.', 'Fills the profile.', 'sn')
n('Ldap.PhoneAttribute', 'The attribute with the phone number (default `telephoneNumber`).', 'Rarely.', 'Fills the profile.', 'mobile')
n('Ldap.GroupSearchBase', 'Where to search for groups.', 'With group mapping.', 'Limits the search.', 'DC=corp,DC=com')
n('Ldap.GroupFilter', 'The filter that finds the groups of a user (`{0}` is the user\'s DN).', 'With group mapping.', 'Tells the Server how groups relate to users.', '(&(objectClass=group)(member={0}))')
n('Ldap.GroupMemberAttribute', 'The attribute of a group that lists its members (default `member`).', 'Rarely.', 'Used for nested groups.', 'member')
n('Ldap.MemberOfAttribute', 'The attribute of the **user** that lists their groups (`memberOf` in Active Directory).', 'Active Directory.', 'A faster way to read the direct groups.', 'memberOf')
n('Ldap.NestedGroups', 'Also find groups of groups (depth 5).', 'When rights are given to parent groups.', 'Off by default: it costs more directory calls.', True)
n('Ldap.TimeoutSeconds', 'The time limit of a directory call (default 5).', 'Slow directories.', 'A hung directory must not hang sign-in.', 10)
n('Ldap.FollowReferrals', 'Follow LDAP referrals to other servers.', 'Multi-domain forests.', 'Off by default: a referral could send the connection somewhere you did not plan.', True)
n('Ldap.Mode', '`LdapOnly`, `LocalThenLdap`, `LdapThenLocal`. See [enums-reference.md](enums-reference.md#ldapmode).', 'When local and directory passwords coexist.', 'Decides which password is tried first.', 'LdapThenLocal')
n('Ldap.SyncOnLogin', 'Update the person and the group mappings from the directory at every sign-in (default `true`).', 'Turn off to freeze data after the first sign-in.', 'There is no background sync, so sign-in is when data is refreshed.', True)
n('Ldap.RevealDirectoryAccountState', 'Tell the user why the directory refused (`ldap_account_disabled`, expired password). Off by default: the generic answer is used.', 'An internal product where clear messages help the help desk.', 'Detailed errors reveal account states to anyone who can type a user name.', True)
